  `tab` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'main' COMMENT '所属选项卡',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

