DROP TABLE IF EXISTS `dou_data`;
CREATE TABLE `dou_data` (
  `id` smallint(5) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `parent_code` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '父级编码',
  `theme` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'default' COMMENT '所属主题',
  `data_group` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'common' COMMENT '数据分组',
  `data_item` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '关联项标识',
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '名称',
  `code` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '编码',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '图片',
  `text` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文本内容',
  `link` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '跳转链接',
  `is_class` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否分组',
  `is_locked` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `sort` tinyint(1) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO dou_data VALUES('1','','default','index','','公司简介','about','p9ajemt.file','公司成立于2013年，注册地位于福建省，是一家专注于科技研发、智能制造、金融服务等的高新技术企业。公司以核心使命：\"创新驱动发展\"\"为客户创造价值\"为理念，致力于提供行业解决方案、研发前沿技术、打造优质产品。公司已取得丰硕的成果。目前，我们的业务网络 市场覆盖广泛，产品与服务已拓展至全国XX个省市/全球XX个国家和地区。在项目实施与产品应用上，成功打造了多个 标杆案例，充分验证了我们的实力与可靠性。同时，公司积极履行社会责任，创造了显著的经济效益与社会价值，年产值稳步增长，为地方经济发展和人才就业做出了积极贡献。','','0','0','50');

DROP TABLE IF EXISTS `dou_file`;
CREATE TABLE `dou_file` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `uploader_type` enum('admin','user','work') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'admin' COMMENT '上传者类型',
  `uploader_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '上传者ID',
  `number` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '文件编号(唯一)',
  `file` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '文件路径',
  `module` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '所属模块',
  `item_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '关联内容ID',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '文件类型',
  `size` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '文件大小(字节)',
  `thumb_size` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '缩略图大小(字节)',
  `original_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '原始文件名',
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'MIME 类型',
  `storage_driver` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'local' COMMENT '存储驱动',
  `draft_token` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '草稿令牌',
  `draft_expire_at` datetime DEFAULT NULL,
  `status` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'owned' COMMENT '状态 draft/owned',
  `last_used_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `number` (`number`),
  KEY `idx_uploader_status_expire` (`uploader_type`,`uploader_id`,`status`,`draft_expire_at`)
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

