INSERT INTO dou_page VALUES('4','contact','1','联系我们','<p>通讯地址：<br/><span style=\"color:#D7D7D7;\">--------------------------------------------------------------------------------------------------------------------------------</span><br/>福建省漳州市芗城区，邮编363000<br/><br/>客服邮箱：<br/><span style=\"color:#D7D7D7;\">--------------------------------------------------------------------------------------------------------------------------------</span><br/>DouPHP售后服务邮箱：email@email.com<br/>DouPHP业务受理邮箱：<span>email@email.com</span><br/>如您需要订制开发请在邮件中注明您的大概要求，我们将在一个工作日内给予回复。<br/><br/>客服电话：<br/><span style=\"color:#D7D7D7;\">--------------------------------------------------------------------------------------------------------------------------------</span><br/><span>DouPHP</span>的建站咨询电话为 0596-1234567。<br/>客服电话工作时间为周一至周日 8:00-20:00，节假日不休息，免长途话费。<br/>我们将随时为您献上真诚的服务。<br/></p>','联系我们','联系我们','','editor');
