DROP TABLE IF EXISTS `dou_parameter`;
CREATE TABLE `dou_parameter` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `name` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数键名',
  `lang` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '参数显示名',
  `value` text COLLATE utf8mb4_unicode_ci COMMENT '参数值',
  `cue` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '提示说明',
  `group` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT '所属分组',
  `lock` tinyint(1) unsigned NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `sort` tinyint(1) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO dou_parameter VALUES('1','miniprogram_appid','AppID/小程序ID','','微信公众平台：mp.weixin.qq.com，“开发->开发设置”里获取','miniprogram','0','50');
INSERT INTO dou_parameter VALUES('2','miniprogram_appsecret','AppSecret/小程序密钥','','微信公众平台：mp.weixin.qq.com，“开发->开发设置”里获取','miniprogram','0','50');
INSERT INTO dou_parameter VALUES('3','miniprogram_pay_mch_id','微信支付商户号（如果没有使用到微信支付无需设置）','','微信商户平台：pay.weixin.qq.com，“账户中心->商户信息”里获取，另外需要在“产品中心-》AppID账号管理”将上面填写的AppID对应的小程序进行绑定','miniprogram','0','50');
INSERT INTO dou_parameter VALUES('4','miniprogram_pay_key','微信支付商户API密钥','','微信商户平台：pay.weixin.qq.com，“账户中心->API安全->设置APIv2密钥”里获取','miniprogram','0','50');
INSERT INTO dou_parameter VALUES('5','miniprogram_domain','站点网址（业务域名）','','请输入线上正式网址（以 / 结束），如果是本机调试可以输入本机地址，但正式发布小程序之前一定要改为线上网址','miniprogram','0','50');

DROP TABLE IF EXISTS `dou_product`;
CREATE TABLE `dou_product` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `category_id` smallint(5) NOT NULL DEFAULT '0' COMMENT '分类ID',
  `operator_type` enum('admin','work') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'admin' COMMENT '创建者类型',
  `operator_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建者ID',
  `brand_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '品牌ID',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品标题',
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'URL标识',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '价格',
  `level_price` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '会员等级价(序列化数组)',
  `promote_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '促销价',
  `promote_start_at` datetime DEFAULT NULL,
  `promote_end_at` datetime DEFAULT NULL,
  `stock` smallint(6) unsigned NOT NULL DEFAULT '0' COMMENT '库存',
  `defined` text COLLATE utf8mb4_unicode_ci COMMENT '自定义字段(序列化数组)',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '商品详情',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '缩略图',
  `model` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '型号',
  `point` smallint(8) unsigned NOT NULL DEFAULT '0' COMMENT '赠送积分',
  `sales` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '销量',
  `keywords` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'SEO关键词',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'SEO描述',
  `sort` smallint(5) unsigned NOT NULL DEFAULT '50' COMMENT '排序',
  `status` tinyint(1) unsigned NOT NULL DEFAULT '1' COMMENT '状态:1启用,0禁用',
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_slug` (`slug`),
  KEY `idx_operator` (`operator_type`,`operator_id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO dou_product VALUES('1','5','admin','0','0','插座面板','','3680.00','','0.00','0000-00-00 00:00:00','0000-00-00 00:00:00','100','','<p style=\"text-wrap-mode: wrap;\"><strong>一、产品概述</strong></p><p style=\"text-wrap-mode: wrap;\">我们很荣幸向您介绍我们公司的最新产品。这款产品是经过精心研发和设计的，旨在满足消费者的需求和提供高品质的体验。我们将详细介绍产品的特点、功能、优势和适用范围，希望能为您提供全面的了解。</p><p style=\"text-wrap-mode: wrap;\"><br/></p><p style=\"text-wrap-mode: wrap;\"><strong>二、产品特点</strong></p><p style=\"text-wrap-mode: wrap;\">1.创新设计:我们的产品注重创新，追求独特的外观设计和先进的技术应用，确保产品与众不同。</p><p style=\"text-wrap-mode: wrap;\">2.卓越性能:我们致力于提供卓越的产品性能。无论是在速度、稳定性还是使用寿命方面，我们都将为您带来无与伦比的体验。</p><p style=\"text-wrap-mode: wrap;\">3.高品质材料:我们使用优质材料来制造产品，确保产品的耐用性和可靠性。产品不仅具有良好的外观，还具备出色的性能。</p><p style=\"text-wrap-mode: wrap;\">4.人性化设计:我们充分考虑用户的需求和使用习惯，努力提供贴合用户体验的产品设计。操作简便功能齐全，轻松满足用户的使用需求。</p><p style=\"text-wrap-mode: wrap;\"><br/></p><p style=\"text-wrap-mode: wrap;\"><strong>三、产品功能</strong></p><p style=\"text-wrap-mode: wrap;\">我们的产品具备以下出色的功能:</p><p style=\"text-wrap-mode: wrap;\">1.xxx功能:通过使用最新的技术，我们的产品实现了xxx功能，为用户提供了便捷和高效的解决方案</p><p style=\"text-wrap-mode: wrap;\">2.xxx功能:我们的产品还拥有xxx功能，通过优化设计和卓越的性能，提供给用户精确、稳定的体验。</p><p style=\"text-wrap-mode: wrap;\">3.xxx功能:除了以上功能，我们还为产品添加了xxx功能，以满足不同用户的需求和期望。</p><p style=\"text-wrap-mode: wrap;\"><br/></p><p style=\"text-wrap-mode: wrap;\"><strong>四、产品优势</strong></p><p style=\"text-wrap-mode: wrap;\">1.高性价比:我们的产品在市场上具有极高的性价比。虽然价格合理，但不妥协于品质和性能</p><p style=\"text-wrap-mode: wrap;\">2.优质服务:我们承诺提供完善的售后服务，确保您在使用过程中的满意度。无论是在产品保修还是技术支持方面，我们始终与您同在。</p><p style=\"text-wrap-mode: wrap;\">3.可靠性:以用户体验为导向，我们的产品经过严格的品质检测，以确保产品的可靠性和稳定性,</p><p style=\"text-wrap-mode: wrap;\">4.品牌信誉:作为一家备受信赖的品牌，我们以诚实守信的原则经营，并努力满足客户的需求。多年来，我们获得了良好的口碑和客户的高度认可。</p><p style=\"text-wrap-mode: wrap;\"><br/></p><p style=\"text-wrap-mode: wrap;\"><strong>五、适用范围</strong></p><p style=\"text-wrap-mode: wrap;\">我们的产品适用于各种场景和人群，无论是个人用户还是企业客户。不论您是个人用户还是企业客户我们的产品将为您提供卓越的性能和可的服务，满足不同需求。</p><p style=\"text-wrap-mode: wrap;\"><br/></p><p style=\"text-wrap-mode: wrap;\"><strong>六、结语</strong></p><p style=\"text-wrap-mode: wrap;\">感谢您对我们产品的关注和信任。我们将继续努力，提供更好的产品和服务，并不断超越自我，为用户带来更多的惊喜和价值，如果您对产品有任何疑问或想要进一步了解，请随时与我们联系，我们将竭诚为您服务。</p><p style=\"text-wrap-mode: wrap;\">希望通过以上产品介绍，能够使您对我们的产品有更深入的了解，并对我们的产品产生浓厚的兴趣。期待与您的进一步合作!</p><p><br/></p>','tuw5cdr.file','','0','0','','','50','1','2013-06-26 19:01:52');
INSERT INTO dou_product VALUES('2','4','admin','0','0','手持吸层器','','5300.00','','0.00','0000-00-00 00:00:00','0000-00-00 00:00:00','100','','<p style=\"text-wrap-mode: wrap;\"><strong>一、产品概述</strong></p><p style=\"text-wrap-mode: wrap;\">我们很荣幸向您介绍我们公司的最新产品。这款产品是经过精心研发和设计的，旨在满足消费者的需求和提供高品质的体验。我们将详细介绍产品的特点、功能、优势和适用范围，希望能为您提供全面的了解。</p><p style=\"text-wrap-mode: wrap;\"><br/></p><p style=\"text-wrap-mode: wrap;\"><strong>二、产品特点</strong></p><p style=\"text-wrap-mode: wrap;\">1.创新设计:我们的产品注重创新，追求独特的外观设计和先进的技术应用，确保产品与众不同。</p><p style=\"text-wrap-mode: wrap;\">2.卓越性能:我们致力于提供卓越的产品性能。无论是在速度、稳定性还是使用寿命方面，我们都将为您带来无与伦比的体验。</p><p style=\"text-wrap-mode: wrap;\">3.高品质材料:我们使用优质材料来制造产品，确保产品的耐用性和可靠性。产品不仅具有良好的外观，还具备出色的性能。</p><p style=\"text-wrap-mode: wrap;\">4.人性化设计:我们充分考虑用户的需求和使用习惯，努力提供贴合用户体验的产品设计。操作简便功能齐全，轻松满足用户的使用需求。</p><p style=\"text-wrap-mode: wrap;\"><br/></p><p style=\"text-wrap-mode: wrap;\"><strong>三、产品功能</strong></p><p style=\"text-wrap-mode: wrap;\">我们的产品具备以下出色的功能:</p><p style=\"text-wrap-mode: wrap;\">1.xxx功能:通过使用最新的技术，我们的产品实现了xxx功能，为用户提供了便捷和高效的解决方案</p><p style=\"text-wrap-mode: wrap;\">2.xxx功能:我们的产品还拥有xxx功能，通过优化设计和卓越的性能，提供给用户精确、稳定的体验。</p><p style=\"text-wrap-mode: wrap;\">3.xxx功能:除了以上功能，我们还为产品添加了xxx功能，以满足不同用户的需求和期望。</p><p style=\"text-wrap-mode: wrap;\"><br/></p><p style=\"text-wrap-mode: wrap;\"><strong>四、产品优势</strong></p><p style=\"text-wrap-mode: wrap;\">1.高性价比:我们的产品在市场上具有极高的性价比。虽然价格合理，但不妥协于品质和性能</p><p style=\"text-wrap-mode: wrap;\">2.优质服务:我们承诺提供完善的售后服务，确保您在使用过程中的满意度。无论是在产品保修还是技术支持方面，我们始终与您同在。</p><p style=\"text-wrap-mode: wrap;\">3.可靠性:以用户体验为导向，我们的产品经过严格的品质检测，以确保产品的可靠性和稳定性,</p><p style=\"text-wrap-mode: wrap;\">4.品牌信誉:作为一家备受信赖的品牌，我们以诚实守信的原则经营，并努力满足客户的需求。多年来，我们获得了良好的口碑和客户的高度认可。</p><p style=\"text-wrap-mode: wrap;\"><br/></p><p style=\"text-wrap-mode: wrap;\"><strong>五、适用范围</strong></p><p style=\"text-wrap-mode: wrap;\">我们的产品适用于各种场景和人群，无论是个人用户还是企业客户。不论您是个人用户还是企业客户我们的产品将为您提供卓越的性能和可的服务，满足不同需求。</p><p style=\"text-wrap-mode: wrap;\"><br/></p><p style=\"text-wrap-mode: wrap;\"><strong>六、结语</strong></p><p style=\"text-wrap-mode: wrap;\">感谢您对我们产品的关注和信任。我们将继续努力，提供更好的产品和服务，并不断超越自我，为用户带来更多的惊喜和价值，如果您对产品有任何疑问或想要进一步了解，请随时与我们联系，我们将竭诚为您服务。</p><p style=\"text-wrap-mode: wrap;\">希望通过以上产品介绍，能够使您对我们的产品有更深入的了解，并对我们的产品产生浓厚的兴趣。期待与您的进一步合作!</p><p><br/></p>','sk358ym.file','','0','2','','','50','1','2013-06-26 21:27:21');
